import{_ as i,C as t,o as r,c as d,j as o,a as l,G as s,a3 as c}from"./chunks/framework.Bvm_liKL.js";const y=JSON.parse('{"title":"Contributing","description":"Branching strategy, commit conventions, PR checks, and code standards","frontmatter":{"title":"Contributing","description":"Branching strategy, commit conventions, PR checks, and code standards"},"headers":[],"relativePath":"en/dev/getting-started/contributing.md","filePath":"en/dev/getting-started/contributing.md"}'),h={name:"en/dev/getting-started/contributing.md"};function p(g,e,u,m,b,k){const a=t("ArticleMetadata"),n=t("HelpUsImprove");return r(),d("div",null,[e[0]||(e[0]=o("h1",{id:"contributing",tabindex:"-1"},[l("Contributing "),o("a",{class:"header-anchor",href:"#contributing","aria-label":'Permalink to "Contributing"'},"​")],-1)),s(a),s(n),e[1]||(e[1]=c(`<p>The main development branch is <code>net6</code>. <code>main</code> is a legacy branch and is effectively inactive. All PRs should target <code>net6</code>.</p><h2 id="branching-strategy" tabindex="-1">Branching strategy <a class="header-anchor" href="#branching-strategy" aria-label="Permalink to &quot;Branching strategy&quot;">​</a></h2><p>There is only one active development branch: <strong><code>net6</code></strong>.</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>net6 (main development branch)</span></span>
<span class="line"><span>  ├─ feature/xxx (feature branches)</span></span>
<span class="line"><span>  ├─ fix/yyy (fix branches)</span></span>
<span class="line"><span>  └─ PR → net6</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>Whenever <code>net6</code> receives new commits, <code>sync-net6-to-net10.yml</code> automatically merges the changes into the <code>net10</code> branch (the .NET 10 migration branch). Details at the end of this page.</p><div class="warning custom-block"><p class="custom-block-title">Do not push directly to main</p><p>Although <code>prcheck.yml</code> allows PRs to <code>main</code>, all real development happens on <code>net6</code>. Unless a maintainer explicitly asks for it, do not submit to <code>main</code>.</p></div><h2 id="commit-message-conventions" tabindex="-1">Commit message conventions <a class="header-anchor" href="#commit-message-conventions" aria-label="Permalink to &quot;Commit message conventions&quot;">​</a></h2><p>The project follows <a href="https://www.conventionalcommits.org/" target="_blank" rel="noreferrer">Conventional Commits</a>, and <code>git-cliff</code> generates the changelog from commit messages automatically.</p><h3 id="mapping-prefixes-to-changelog-groups" tabindex="-1">Mapping prefixes to changelog groups <a class="header-anchor" href="#mapping-prefixes-to-changelog-groups" aria-label="Permalink to &quot;Mapping prefixes to changelog groups&quot;">​</a></h3><p>The <code>commit_parsers</code> section of <code>build/cliff.toml</code> decides which group a commit lands in. <strong>Chinese prefixes are recognized as well</strong>, which is the biggest difference between this setup and standard Conventional Commits:</p><table tabindex="0"><thead><tr><th>Commit message prefix</th><th>Changelog group</th></tr></thead><tbody><tr><td><code>feat</code> / <code>add</code> / <code>新增</code> / <code>添加</code></td><td>🚀 New features</td></tr><tr><td><code>fix</code> / <code>修复</code></td><td>🐛 Fixes</td></tr><tr><td><code>refactor</code></td><td>🚜 Refactoring</td></tr><tr><td><code>improve</code> / <code>改进</code> / <code>优化</code></td><td>⚡ Experience improvements</td></tr><tr><td><code>delete</code> / <code>删除</code> / <code>移除</code></td><td>❌ Removed features</td></tr><tr><td><code>doc</code></td><td>📚 Documentation changes</td></tr><tr><td><code>style</code></td><td>🎨 Formatting</td></tr><tr><td><code>test</code></td><td>🧪 Tests</td></tr><tr><td><code>chore</code> / <code>ci</code></td><td>⚙️ Chores</td></tr><tr><td><code>Revert</code></td><td>◀️ Reverts</td></tr><tr><td><code>版本</code> / <code>version</code> / <code>更新版本号</code></td><td>🎉 Version bumps</td></tr><tr><td>Anything else</td><td>💼 Other changes</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">No commit is ever dropped</p><p><code>filter_commits = false</code>, and the last rule is <code>{ message = &quot;.*&quot;, group = &quot;其他更改&quot; }</code>. Even the sloppiest commit message ends up in the changelog, just under &quot;💼 Other changes&quot;. If you want a readable changelog, use the prefixes.</p></div><p>The following categories are skipped explicitly (<code>skip = true</code>) and never appear in the changelog:</p><ul><li><code>chore(release): prepare for ...</code></li><li><code>chore(deps...)</code> — Dependabot dependency updates</li><li><code>chore(pr)</code> / <code>chore(pull)</code></li><li><code>Merge branch ...</code></li></ul><div class="tip custom-block"><p class="custom-block-title">A typical commit</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">feat(plugin</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">): allow plugins to register global hotkeys</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">Add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> a</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> RegisterHotkey</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> method</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> to</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> IPluginHost</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> so</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> plugins</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> can</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> register</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> global</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">hotkeys</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> during</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Initialize.</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">Closes</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> #1234</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><p>Writing <code>#1234</code> in a commit message gets turned into a link to the corresponding issue in the community repository by <code>link_parsers</code>.</p></div><h2 id="pr-check-gates" tabindex="-1">PR check gates <a class="header-anchor" href="#pr-check-gates" aria-label="Permalink to &quot;PR check gates&quot;">​</a></h2><p>Opening a PR against <code>net6</code> or <code>main</code> triggers the following checks:</p><h3 id="_1-prcheck-yml-—-build-and-packaging" tabindex="-1">1. prcheck.yml — build and packaging <a class="header-anchor" href="#_1-prcheck-yml-—-build-and-packaging" aria-label="Permalink to &quot;1. prcheck.yml — build and packaging&quot;">​</a></h3><p><strong>Triggers</strong>: PR opened/synchronize, with <code>paths-ignore: [&quot;**/*.md&quot;]</code> (pure Markdown changes are skipped).</p><p><strong>Matrix</strong>: builds <code>AnyCPU</code> and <code>x86</code> in parallel.</p><p><strong>Key checks</strong>:</p><ul><li><code>dotnet restore --locked-mode</code> — any <code>PackageReference</code> change must come with an updated <code>packages.lock.json</code>, otherwise it fails</li><li>Builds the <code>Debug</code> configuration with <code>/p:RunAnalyzers=false</code> (skips analyzers for speed)</li><li>Verifies the VSTO DLL was produced (<code>Microsoft.Office.Tools.Common.v4.0.Utilities.dll</code> must exist)</li><li>Verifies the main executable was produced</li><li>Packages the output and uploads it as an artifact</li></ul><p>About certificates: if the <code>CERT_PFX_BASE64</code> secret is present, the real certificate is imported; otherwise a self-signed certificate is generated. PRs from forks pass too (they use the self-signed path).</p><h3 id="_2-linter-yml-—-code-checks" tabindex="-1">2. linter.yml — code checks <a class="header-anchor" href="#_2-linter-yml-—-code-checks" aria-label="Permalink to &quot;2. linter.yml — code checks&quot;">​</a></h3><p><strong>Triggers</strong>: push/PR to <code>net6</code>, Markdown ignored as above.</p><p><strong>Linter</strong>: <code>super-linter v8.6.0</code>, but with <code>DISABLE_ERRORS: true</code> (<strong>reports only, never blocks the PR</strong>).</p><p><strong>Disabled checks</strong>: <code>VALIDATE_BIOME_FORMAT</code>, <code>VALIDATE_SPELL_CODESPELL</code>, <code>VALIDATE_GITLEAKS</code> (secret scanning is off because of the self-signed test certificate).</p><div class="tip custom-block"><p class="custom-block-title">The linter will not fail your PR</p><p>Even with formatting problems, <code>linter.yml</code> only reports them in the summary and will not block the merge. Fixing them is still recommended to keep code quality up.</p></div><h2 id="code-standards" tabindex="-1">Code standards <a class="header-anchor" href="#code-standards" aria-label="Permalink to &quot;Code standards&quot;">​</a></h2><p>The complete standards live in the <code>community/rules/</code> directory. Listed here are the ones people trip over most.</p><h3 id="general-rules-general-md" tabindex="-1">General rules (general.md) <a class="header-anchor" href="#general-rules-general-md" aria-label="Permalink to &quot;General rules (general.md)&quot;">​</a></h3><ol><li><strong>All user-visible text must go through i18n</strong>. Never hardcode Chinese or English strings in XAML or code. Use <code>Strings.GetString(&quot;KeyName&quot;)</code>.</li><li><strong>The result of <code>Geometry.Parse()</code> is read-only</strong>. You must <code>Clone()</code> before modifying it, otherwise it throws.</li><li><strong>Never touch the visual tree in the <code>AfterBuild</code> event</strong>. Exceptions get swallowed by a try-catch, so you will not see the error. Defer visual tree work to the <code>Loaded</code> event.</li><li><strong>The two-argument <code>Thickness</code> constructor is banned</strong>. WPF on .NET 6 does not support <code>Thickness(double, double)</code>, so use the four-argument form <code>Thickness(left, top, right, bottom)</code>.</li><li><strong>Private fields use a <code>_</code> prefix</strong>, for example <code>_stylusDownTimestamp</code>. XAML element names use PascalCase, for example <code>CardEnableInkFade</code>.</li><li><strong>Semantics of IsHighlighter</strong>: always <code>false</code> for the regular pen and laser pointer; for the highlighter it is <code>!Settings.Canvas.HighlighterOverlapEnabled</code> (false in overlap mode, true in transparent mode).</li></ol><h3 id="xaml-control-rules-xaml-controls-md" tabindex="-1">XAML control rules (xaml_controls.md) <a class="header-anchor" href="#xaml-control-rules-xaml-controls-md" aria-label="Permalink to &quot;XAML control rules (xaml_controls.md)&quot;">​</a></h3><ol><li><strong>No <code>&lt;ComboBox&gt;</code> may set <code>Width</code>, <code>MinWidth</code>, or <code>MaxWidth</code></strong>. Remove those properties and let the ComboBox size itself.</li><li><strong>Settings entries with a toggle must use <code>LabeledSettingsCard</code></strong>. Do not hand-nest a <code>ui:ToggleSwitch</code> inside a <code>ui:SettingsCard</code>.</li><li><strong><code>LabeledSettingsCard</code> is banned inside <code>Expander.Items</code></strong>. Only <code>ui:SettingsCard</code> is allowed inside an Expander (otherwise you get visual nesting problems).</li><li><strong><code>&lt;SymbolIcon&gt;</code> must set <code>FontSize</code> explicitly</strong>, otherwise it blows up in size at certain DPI settings.</li><li><strong><code>&lt;ComboBox&gt;</code> / <code>&lt;ComboBoxItem&gt;</code> must not set <code>Background</code></strong>. It overrides the theme style and breaks the selected state.</li></ol><h3 id="settings-page-rules-settings-pages-md" tabindex="-1">Settings page rules (settings_pages.md) <a class="header-anchor" href="#settings-page-rules-settings-pages-md" aria-label="Permalink to &quot;Settings page rules (settings_pages.md)&quot;">​</a></h3><p>This is the longest standards document (378 lines). The core requirements:</p><ol><li><strong>Every settings entry needs a <code>Header</code> and a <code>Description</code></strong>. <code>Header</code> uses an i18n string; <code>Description</code> should clearly explain what the option does and what it affects.</li><li><strong>Toggles go on the right side of the card</strong>, using <code>&lt;LabeledSettingsCard&gt;</code>.</li><li><strong>Group complex settings with an <code>Expander</code></strong> to keep advanced options collapsed.</li><li><strong>Settings changes must call main-window methods through <code>SettingsActionHub</code></strong>, not by touching <code>MainWindow</code> fields directly.</li><li><strong>Saving settings is automatic</strong>. <code>SettingsManager</code> calls <code>SaveSettingsToFile()</code> after a property changes, so you do not need to save explicitly.</li></ol><h3 id="toolbar-rules-toolbar-md" tabindex="-1">Toolbar rules (toolbar.md) <a class="header-anchor" href="#toolbar-rules-toolbar-md" aria-label="Permalink to &quot;Toolbar rules (toolbar.md)&quot;">​</a></h3><ol><li><strong>The floating toolbar (FloatingToolbar) and the whiteboard toolbar (BoardToolbar) are two independent systems</strong> with no shared interface.</li><li><strong>Toolbar items are discovered automatically via reflection</strong>. Implement <code>IToolbarItem</code> with a public parameterless constructor and <code>ToolbarRegistry.Discover()</code> will find it.</li><li><strong>Plugin toolbar items are registered through <code>RegisterToolbarItem()</code></strong> and get wrapped in a <code>PluginToolbarItemWrapper</code> to adapt them to <code>IToolbarItem</code>.</li><li><strong>Toolbar layouts are saved in <code>Configs/ToolbarConfigs/&lt;name&gt;.json</code></strong>, serialized with Newtonsoft.Json, with a backup mechanism (<code>.json.bak</code>).</li></ol><h3 id="popup-rules-popups-menus-md" tabindex="-1">Popup rules (popups_menus.md) <a class="header-anchor" href="#popup-rules-popups-menus-md" aria-label="Permalink to &quot;Popup rules (popups_menus.md)&quot;">​</a></h3><ol><li><strong>Every <code>&lt;Popup&gt;</code> must be registered with <code>PopupManagerHelper</code></strong>, otherwise <code>CloseAllPopups()</code> will not manage it.</li><li><strong>Popup content should use <code>PopupShellContent</code> or <code>PopupTabShellContent</code></strong>. These two controls provide a consistent title bar, close button, and shadow effect.</li><li><strong><code>StaysOpen=&quot;true&quot;</code> + <code>Focusable=&quot;true&quot;</code></strong>. That way the popup does not close immediately on an outside click (PopupManager handles it centrally).</li></ol><h2 id="testing-requirements" tabindex="-1">Testing requirements <a class="header-anchor" href="#testing-requirements" aria-label="Permalink to &quot;Testing requirements&quot;">​</a></h2><p><code>CONTRIBUTING.md</code> spells out two categories of testing requirements:</p><h3 id="hand-written-code" tabindex="-1">Hand-written code <a class="header-anchor" href="#hand-written-code" aria-label="Permalink to &quot;Hand-written code&quot;">​</a></h3><ol><li><strong>A basic build test</strong> — avoid submitting incomplete code.</li><li><strong>A basic run test</strong> — for UI changes use the &quot;three-step check&quot; (first the styling, then the behavior, then whether i18n is complete); for backend changes, test what you changed.</li></ol><h3 id="ai-assisted-code" tabindex="-1">AI-assisted code <a class="header-anchor" href="#ai-assisted-code" aria-label="Permalink to &quot;AI-assisted code&quot;">​</a></h3><ol><li><strong>When using AI assistance you must understand every line of the change.</strong></li><li><strong>Run comprehensive runtime tests</strong> — cover every area that might be affected, do regression testing, and fix issues specifically.</li><li><strong>Blindly using AI to fix things is strictly forbidden.</strong> When a problem shows up, carefully review the suspicious commits from the change.</li></ol><div class="danger custom-block"><p class="custom-block-title">Serious consequences</p><p>Line 22 of CONTRIBUTING.md warns explicitly: &quot;If we find that you are pretending to understand what you do not and refuse to correct it, we will remove you from the contributor list and permanently ban you from contributing code.&quot;</p></div><h2 id="other-workflows" tabindex="-1">Other workflows <a class="header-anchor" href="#other-workflows" aria-label="Permalink to &quot;Other workflows&quot;">​</a></h2><h3 id="publish-sdk-nuget-yml" tabindex="-1">publish-sdk-nuget.yml <a class="header-anchor" href="#publish-sdk-nuget-yml" aria-label="Permalink to &quot;publish-sdk-nuget.yml&quot;">​</a></h3><p>Packs and publishes <code>InkCanvas.PluginSdk</code> and <code>InkCanvas.Controls</code> to nuget.org.</p><p><strong>Two ways to trigger it</strong>:</p><ul><li>Push a tag shaped like <code>sdk-v1.7.19.9</code> — forces publishing with the version from the tag</li><li>Manual <code>workflow_dispatch</code> — accepts <code>branch</code> (default <code>net6</code>) and <code>version</code>; leaving <code>version</code> empty uses the version NBGV computes from git state</li></ul><p>It requires the repository secret <code>NUGET_API_KEY</code>. The concurrency group is <code>publish-sdk-nuget</code> with <code>cancel-in-progress: false</code> so two publishes cannot interrupt each other.</p><h3 id="sync-net6-to-net10-yml" tabindex="-1">sync-net6-to-net10.yml <a class="header-anchor" href="#sync-net6-to-net10-yml" aria-label="Permalink to &quot;sync-net6-to-net10.yml&quot;">​</a></h3><p>After a push to <code>net6</code> (or a manual trigger), it merges <code>net6</code> into <code>net10</code>. This workflow does far more than a plain merge:</p><ol><li>Merges <code>net6</code> → <code>net10</code>, <strong>resolving conflicts automatically</strong>: csproj files take the <code>net6</code> version, then the TFM is switched back to net10</li><li>Deletes the old <code>packages.lock.json</code></li><li>Tries <code>restore</code> + <code>build</code> first (most packages support both net6 and net10, so nothing needs changing)</li><li>Only if the build fails does it upgrade all NuGet packages to their latest stable versions and re-run <code>restore</code> + <code>build</code></li><li><strong>Pushes only if the build succeeds</strong>, otherwise it aborts and raises an alert</li></ol><div class="tip custom-block"><p class="custom-block-title">You can ignore the net10 branch</p><p><code>net10</code> is the migration branch, maintained automatically by this workflow. Day-to-day development only needs <code>net6</code>, unless you get a sync failure alert.</p></div><h2 id="next-steps" tabindex="-1">Next steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next steps&quot;">​</a></h2><ul><li><a href="./environment">Environment setup</a> — installing VS 2022, the .NET 6 SDK, and the VSTO tooling</li><li><a href="./build-and-run">Build and run</a> — the full build, versioning, CI, and packaging flow</li><li><a href="./../core/conventions">Code conventions</a> — the complete reference for everything under <code>community/rules/</code></li></ul>`,60))])}const v=i(h,[["render",p]]);export{y as __pageData,v as default};
